// Featured Cyrus mods (2026-10-13): the owner's hand-picked list for the marketing surfaces (/mods/cyrus and the cyrus.my
// landing). The list lives in ONE Setting (`cyrus_featured_pages`, a JSON array of CyrusModPage ids in display order), so
// there is no migration and every change is an audited admin action. A listing shows only while it is PUBLIC and not hidden
// by moderation; an unpublished or taken-down page silently drops out (the id stays in the list and comes back if it is
// restored). Pure helpers first, the DB reader last.
import { cyrusDb } from "../cyrus/db";

import { db } from "../db";
import { getSetting } from "../settings";
import { flightFailedVerdict } from "../cyrus/app/failure";

export const FEATURED_KEY = "cyrus_featured_pages";
export const FEATURED_MAX = 12;

export function parseFeatured(raw: string | null | undefined): string[] {
  if (!raw) return [];
  try {
    const v = JSON.parse(raw) as unknown;
    if (!Array.isArray(v)) return [];
    const out: string[] = [];
    for (const x of v) if (typeof x === "string" && /^[A-Za-z0-9_-]{1,64}$/.test(x) && !out.includes(x)) out.push(x);
    return out.slice(0, FEATURED_MAX);
  } catch { return []; }
}

export function setFeatured(list: string[], id: string, on: boolean): { ok: true; list: string[] } | { ok: false; error: string } {
  const has = list.includes(id);
  if (!on) return { ok: true, list: list.filter((x) => x !== id) };
  if (has) return { ok: true, list };
  if (list.length >= FEATURED_MAX) return { ok: false, error: `At most ${FEATURED_MAX} mods can be featured. Unfeature one first.` };
  return { ok: true, list: [...list, id] };
}

/** Everything the marketing surfaces show for one card. No account ids, no emails. */
export type FeaturedCard = {
  id: string;
  slug: string;
  title: string;
  tagline: string | null;
  creator: string;
  game: string;
  gameVersion: string | null;
  version: string | null;
  /** average of other accounts' ratings (1-5), null until someone rated it */
  rating: number | null;
  ratings: number;
  stars: number;
  iconUrl: string | null;
};

export type FeaturablePage = { visibility: string; hiddenAt: Date | null };
/** Public AND not taken down: the only pages that may be featured or shown. */
export const isFeaturable = (p: FeaturablePage) => p.visibility === "PUBLIC" && !p.hiddenAt;
export { flightFailedVerdict } from "../cyrus/app/failure"; // rc12: a failed Test Flight is never featured

export async function readFeaturedIds(): Promise<string[]> {
  return parseFeatured(await getSetting(FEATURED_KEY, "").catch(() => ""));
}

/** The public cards, in the owner's order. Empty = hide the section. Never throws. */
export async function loadFeaturedCards(): Promise<FeaturedCard[]> {
  try {
    const ids = await readFeaturedIds();
    if (!ids.length) return [];
    const pages = await cyrusDb.cyrusModPage.findMany({ where: { id: { in: ids }, visibility: "PUBLIC", hiddenAt: null } });
    if (!pages.length) return [];
    const [{ statsFor, listingsFor, toListingView }, { displayUser }, { readModDoc }, { authorUsers }] = await Promise.all([import("./social"), import("./pages"), import("./doc"), import("./username-store")]);
    const [stats, { listings, media }, users] = await Promise.all([
      statsFor(pages).catch(() => new Map()),
      listingsFor(pages.map((p) => p.id)).catch(() => ({ listings: new Map(), media: new Map() })),
      authorUsers([...new Set(pages.map((p) => p.userId))]).catch(() => []),
    ]);
    const byId = new Map(pages.map((p) => [p.id, p]));
    return ids.flatMap((id) => {
      const p = byId.get(id);
      if (!p) return [];
      const d = readModDoc(p.doc);
      if (!d) return [];
      if (flightFailedVerdict(d.testFlight)) return []; // rc12: did not load in the test server: not marketing material
      const st = stats.get(p.id);
      const lv = toListingView(listings.get(p.id) ?? null, media.get(p.id) ?? [], false);
      return [{
        id: p.id, slug: p.slug, title: p.title, tagline: lv.tagline ?? p.tagline, creator: displayUser(users.find((u) => u.id === p.userId) ?? null),
        game: "Minecraft", gameVersion: d.compat.mcVersions[0] ?? null, version: p.latestVersion,
        rating: st?.ratings.average ?? null, ratings: st?.ratings.count ?? 0, stars: st?.stars ?? 0, iconUrl: lv.icon?.url ?? null,
      }];
    });
  } catch (e) {
    console.error("[cyrus-mods] featured read failed", (e as Error).message);
    return [];
  }
}

/** "Make something like this" target: the customer app's New mod page with the mod's slug (prefills the prompt). */
export const makeLikeHref = (slug: string, base = "/dashboard/cyrus/app/new") => `${base}?like=${encodeURIComponent(slug)}`;
/**
 * The ONE switch for every public/community Cyrus-mods surface (NxLabs
 * "Cyrus Mods" section, /mods/cyrus/**, /dashboard/nxlabs/cyrus/**, the
 * community layer, public source/jar downloads, fork).
 *
 * A viewer may see them when EITHER
 *   - Setting cyrus_mods_public_enabled is on (the owner's launch), OR
 *   - they are a private-preview account for "modbuilder" (lib/preview-access.ts;
 *     default: the owner's own customer account).
 * Everyone else gets a plain 404, exactly as if the route did not exist.
 *
 * Indexing: noindex + absent from the sitemap unless the PUBLIC flag is on.
 * A page is listed only when its creator made it PUBLIC and no admin hid it;
 * a creator always sees their own pages (private ones included) while they
 * pass the gate. Fails CLOSED on any DB error.
 */
import { notFound } from "next/navigation";
import { getSettingBool } from "../settings";
import { currentUser } from "../auth";
import { isPreviewUser } from "../preview-access";
export { pageVisibleTo } from "./doc";

export const CYRUS_MODS_PUBLIC_FLAG = "cyrus_mods_public_enabled";
export const CYRUS_PUBLIC_BASE = "/mods/cyrus";
export const CYRUS_PORTAL_BASE = "/dashboard/nxlabs/cyrus";

/** Pure decision (unit-tested). */
export function cyrusRouteDecision(flagOn: boolean, previewUser: boolean): "render" | "not-found" {
  return flagOn || previewUser ? "render" : "not-found";
}

export async function cyrusModsPublicEnabled(): Promise<boolean> {
  try {
    return await getSettingBool(CYRUS_MODS_PUBLIC_FLAG, false);
  } catch {
    return false;
  }
}

export type CyrusAccess = { allowed: boolean; isPublic: boolean; preview: boolean };

export async function cyrusAccessFor(user: { email?: string | null } | null | undefined): Promise<CyrusAccess> {
  const isPublic = await cyrusModsPublicEnabled();
  const preview = !isPublic && (await isPreviewUser(user, "modbuilder"));
  return { allowed: cyrusRouteDecision(isPublic, preview) === "render", isPublic, preview };
}

async function safeUser() {
  try {
    return await currentUser();
  } catch {
    return null;
  }
}

/** Route guard: 404 unless the viewer may see Cyrus mods. Returns the viewer (may be null once launched). */
export async function requireCyrusAccess() {
  const user = await safeUser();
  const access = await cyrusAccessFor(user);
  if (!access.allowed) notFound();
  return { user, access };
}

/** Metadata for gated pages: names the page only when allowed; noindex until launch. */
export async function cyrusMetadata(title: string, description?: string) {
  const user = await safeUser();
  const a = await cyrusAccessFor(user);
  if (!a.allowed) return { title: "Page not found", robots: { index: false, follow: false } };
  return { title, description, robots: a.isPublic ? undefined : { index: false, follow: false } };
}

/** Sitemap paths: only when launched (the caller adds each public page). */
export function cyrusSitemapPaths(flagOn: boolean, slugs: string[]): string[] {
  return flagOn ? [CYRUS_PUBLIC_BASE, ...slugs.map((s) => `${CYRUS_PUBLIC_BASE}/${s}`)] : [];
}
