// Help center URLs (r50). PURE, Edge-safe (middleware imports it). On the Cyrus host the public path is /help; on
// every other host the same pages live at /cyrus-help (an internal-looking name that cannot clash with Nxeon's /help).
export const HELP_BASE_INTERNAL = "/cyrus-help";
export const HELP_BASE_PUBLIC = "/help";

/** Public help path on the Cyrus host -> internal path (null = not a help path). `/plans` is the pricing page. */
export function helpPath(p: string): string | null {
  if (p === HELP_BASE_PUBLIC) return HELP_BASE_INTERNAL;
  if (p === "/plans") return `${HELP_BASE_INTERNAL}/plans`;
  const m = /^\/help\/([a-z0-9][a-z0-9-]{0,63})$/.exec(p);
  return m ? `${HELP_BASE_INTERNAL}/${m[1]}` : null;
}
# cyrus.my vhost, rc10: explicit public-file list instead of try_files to the app (the old catch-all).
# Replaces /etc/nginx/sites-enabled/cyrus-my. Needs the nxeon_web upstream and nxeon_auth zone (conf.d/nxeon-security.conf).
# Owner apply: see deploy/cyrus/README.md (nginx-cyrus-my section) and scripts/cyrus/nginx-cyrus-my-check.sh.
server {
    listen 80;
    listen [::]:80;
    server_name cyrus.my www.cyrus.my;
    root /var/www/cyrus.my;
    index index.html;
    location /.well-known/acme-challenge/ { root /var/www/certbot; }
    location / { return 301 https://$host$request_uri; }
}

# TEMPORARY self-signed HTTPS so Cloudflare 'Full' mode never falls through to another site's default block;
# cyrus-my-finish.sh swaps these two lines for the Let's Encrypt cert.
server {
    listen 443 ssl;
    listen [::]:443 ssl;
    http2 on;
    server_name cyrus.my www.cyrus.my;
    ssl_certificate /etc/letsencrypt/live/cyrus.my/fullchain.pem; # CYRUS_CERT
    ssl_certificate_key /etc/letsencrypt/live/cyrus.my/privkey.pem; # CYRUS_KEY
    ssl_protocols TLSv1.2 TLSv1.3;
    root /var/www/cyrus.my;
    index index.html;
    add_header Strict-Transport-Security "max-age=31536000" always;
    location @pack404 { add_header Cache-Control "no-store" always; return 404; }

    # Cyrus resource packs (owner test). Content-addressed, immutable. Only GET/HEAD of p/<40 hex>.zip.
    location /packs/ {
        location ~ "^/packs/p/([0-9a-f]{40})\.zip$" {
            alias /tank/cyrus-packs/p/$1.zip;
            error_page 404 @pack404;
            default_type application/zip;
            types { }
            limit_except GET HEAD { deny all; }
            add_header Cache-Control "public, max-age=31536000, immutable" always;
            add_header X-Content-Type-Options "nosniff" always;
            add_header Strict-Transport-Security "max-age=31536000" always;
        }
        add_header Cache-Control "no-store" always;
        return 404;
    }

    # CYRUS_APP_PROXY (cyrus.my launch 2026-10-13)
    client_max_body_size 20m;
    error_page 502 503 504 /maintenance.html;
    location = /maintenance.html { root /opt/nxeon/public; internal; }
    location ~ ^/(sign-in|sign-up|auth|login|register)(/|$) {
        limit_req zone=nxeon_auth burst=15 nodelay;
        proxy_pass http://nxeon_web;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_read_timeout 600s;
        proxy_send_timeout 600s;
        proxy_buffering off;
    }
    # App paths (first segment; must match lib/cyrus/bridge/routing.ts, guarded by test/cyrus-launch-check.test.ts and
    # scripts/cyrus/lib/launch-eval.mjs REQUIRED_APP_PREFIXES). "assets" here is the customer asset catalogue page
    # (/assets and /assets?...); the landing's own files live under /assets/ and are carved out by the ^~ block below.
    location ~ ^/(studio|home|new|account|assets|servers|wallet|projects|help|plans|dashboard|legal|api/cyrus|api/auth/google|api/mod-builder|api/nxlabs/cyrus|api/log|_next|vendor)(/|$) {
        proxy_pass http://nxeon_web;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_read_timeout 600s;
        proxy_send_timeout 600s;
        proxy_buffering off;
    }

    # Static landing files: the ONLY files nginx serves from /var/www/cyrus.my. ^~ beats the app-path regex above, so
    # /assets/css/site.css is a file while /assets (no trailing slash) is the app page.
    location = / { try_files /index.html =404; }
    location ^~ /assets/ { try_files $uri =404; expires 7d; add_header Cache-Control "public, max-age=604800" always; }
    location = /status { return 301 /status/; }
    location ^~ /status/ { try_files $uri $uri/index.html =404; add_header Cache-Control "no-cache" always; }
    location = /release.json { try_files /release.json =404; add_header Cache-Control "no-cache" always; }

    # Public files the APP owns (public/ tree + Next metadata routes): proxied by explicit name, never by extension.
    location ^~ /cyrus/ {
        proxy_pass http://nxeon_web;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
    location ~ ^/(favicon\.ico|robots\.txt|sitemap\.xml|manifest\.webmanifest|icon\.png|icon-192\.png|icon-512\.png|apple-touch-icon\.png|nx-mark\.png|opengraph-image|twitter-image)$ {
        proxy_pass http://nxeon_web;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
    # Search Console HTML-file verification (CYRUS_GSC_VERIFICATION=google<16 hex>.html; apps/cyrus-site/publish.sh writes the
    # file into the docroot). Only that exact name shape is served; absent file = 404 from this vhost.
    location ~ ^/google[0-9a-f]{16}\.html$ { try_files $uri =404; default_type text/html; add_header Cache-Control "no-cache" always; }
    location ^~ /.well-known/ {
        proxy_pass http://nxeon_web;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }

    # Everything else is not ours: the landing directory is not browsable and the app is not a catch-all.
    location / { add_header X-Cyrus-Edge denied always; return 404; }
}
