// Which game servers earn Cyrus tokens: exactly the games Cyrus can build for today, read
// from the Cyrus game registry (lib/cyrus/games.ts, status "live"). Adding a live game there
// makes its servers earn tokens and show the checkout line, with no change here.
// Server game families use the same ids as the registry (minecraft, ark, theisle, palworld,
// rust, valheim); anything else (e.g. "bedrock") earns nothing. Client-safe.
import { CYRUS_GAMES } from "../games";

export function cyrusLiveGameIds(): string[] {
  return CYRUS_GAMES.filter((g) => g.status === "live").map((g) => g.id);
}

export function earnsCyrusTokens(gameFamily: string | null | undefined): boolean {
  return !!gameFamily && cyrusLiveGameIds().includes(gameFamily);
}
