 * Stripe retries a failed renewal. An admin override can only raise it.
 */
export function effectiveTier(input: { plan: PlanState; override?: string | null; overrideUntil?: Date | null; now: Date; cfg: TokenConfig }): TokenTier {
  const { plan, now, cfg } = input;
  let tier: TokenTier = "free";
  if (plan && (plan.tier === "katara" || plan.tier === "saka" || plan.tier === "all") && plan.currentPeriodEnd) {
    const end = plan.currentPeriodEnd.getTime();
    const ok =
      ["active", "trialing"].includes(plan.status) ? now.getTime() < end + DAY // a day of slack for webhook lag
      : plan.status === "past_due" ? now.getTime() < end + cfg.plan.pastDueGraceDays * DAY
      : plan.status === "canceled" ? now.getTime() < end
      : false; // incomplete, incomplete_expired, unpaid, paused
    if (ok) tier = plan.tier;
  }
  const o = input.override;
  if ((o === "katara" || o === "saka" || o === "all") && (!input.overrideUntil || input.overrideUntil.getTime() > now.getTime())) tier = maxTier(tier, o);
  return tier;
}

