// Game-server grants
// ---------------------------------------------------------------------------

function perMonth(kind: "initial" | "renew", monthlyCents: number, cfg: TokenConfig): number {
  if (!(monthlyCents > 0)) return 0;
  const r = cfg.grant[kind];
  return Math.round(clamp(round5(r.base + r.perUsd * (monthlyCents / 100)), r.min, r.max));
}

export type ServerGrant = { tokens: number; initialPerMonth: number; renewPerMonth: number; months: number; expiresInDays: number };

/**
 * Tokens for a game-server purchase ("initial") or a paid renewal ("renewal").
 * `monthlyCents` = what the customer actually pays per month (after discounts, before tax).
// Who takes part in the Cyrus token economy. Server only.
//
// Until the owner launches (Setting cyrus_tok_live = true) ONLY private-preview accounts
// (lib/preview-access.ts feature "modbuilder", the same list that can open Cyrus) earn
// grants, see the checkout line or the balance. Everyone else: nothing happens and
// nothing is shown. Fails closed (a settings/DB error = not active).
import { getHost } from "../host";
import { cyrusDb as db } from "../db";
import { loadTokenConfig, type TokenConfig } from "./config";
import { effectiveTier } from "./economy";
import type { TokenTier } from "./config";

/**
 * In the token economy: the owner has launched it for everyone (cyrus_tok_live), the account is on the
 * private preview list, OR the account has EVER held tokens (an account row exists). Once an account has had
 * tokens it stays in the economy for good, even at a zero balance, so its balance stays pinned in the portal.
 */
export async function tokensActiveFor(user: { id?: string | null; email?: string | null } | null | undefined, cfg?: TokenConfig): Promise<boolean> {
  if (!user?.email) return false;
  try {
    const c = cfg ?? (await loadTokenConfig());
    if (c.live) return true;
    if (await getHost().access.isPreviewUser(user, "modbuilder")) return true;
    if (user.id) return !!(await db.cyrusTokenAccount.findUnique({ where: { userId: user.id }, select: { userId: true } }));
    return false;
  } catch {
    return false;
  }
}

export async function tokensActiveForUserId(userId: string, cfg?: TokenConfig): Promise<boolean> {
