  const monthNote = cappedMonths < termMonths ? ` (first ${cappedMonths} month${cappedMonths === 1 ? "" : "s"})` : "";
  switch (coupon.kind) {
    case "PERCENT":
      return coupon.value >= 100 ? `${cappedMonths} month${cappedMonths === 1 ? "" : "s"} free` : `${coupon.value}% off${monthNote}`;
    case "FIXED_CENTS":
      return `$${(coupon.value / 100).toFixed(2)} off`;
    case "SET_PRICE_CENTS":
      return coupon.value === 0 ? "free" : `$${(coupon.value / 100).toFixed(2)} total`;
