/**
 * Live "from $X/mo" figures for SEO titles/descriptions. Reads the same active
 * catalogue rows the checkout charges from (min active plan, per-month
 * normalised) and caches them for 5 minutes. A token whose price can't be read
 * is dropped together with its "from …/mo" phrase — a description with no
 * price is honest; one with a stale hand-typed price is not.
 */
import { db } from "@/lib/db";
import { resolvePriceTokens, type SeoPrices } from "./seo-prices-pure";

type Prices = SeoPrices;
let cache: { at: number; p: Prices } | null = null;

const perMonth = (p: { priceCents: number; termMonths?: number | null }) => {
  const t = p.termMonths ?? 1;
  return t > 1 ? Math.round(p.priceCents / t) : p.priceCents;
};

export async function loadSeoPrices(): Promise<Prices> {
  if (cache && Date.now() - cache.at < 5 * 60_000) return cache.p;
  const [vps, hosting, email, games] = await Promise.all([
    db.plan.findMany({ where: { active: true }, select: { priceCents: true } }).catch(() => []),
    db.hostingPlan.findMany({ where: { active: true }, select: { priceCents: true } }).catch(() => []),
    db.emailPlan.findMany({ where: { active: true }, select: { priceCents: true, termMonths: true } }).catch(() => []),
    db.gamePlan.findMany({ where: { active: true }, select: { priceCents: true, termMonths: true, gameFamily: true } }).catch(() => []),
  ]);
  const min = (xs: number[]) => (xs.length ? Math.min(...xs) : null);
  const game = new Map<string, number>();
  for (const g of games) {
    const v = perMonth(g);
    const cur = game.get(g.gameFamily);
    if (cur == null || v < cur) game.set(g.gameFamily, v);
  }
  const p: Prices = { vps: min(vps.map((x) => x.priceCents)), hosting: min(hosting.map((x) => x.priceCents)), email: min(email.map(perMonth)), game };
  cache = { at: Date.now(), p };
  return p;
}

export async function resolveLivePriceTokens(text: string): Promise<string> {
  return resolvePriceTokens(text, loadSeoPrices);
}
