/** Pure token resolver (separately importable so tests need no database). */
export type SeoPrices = { vps: number | null; hosting: number | null; email: number | null; game: Map<string, number> };
export const usd = (c: number) => `$${(c / 100).toFixed(2)}`;

/** Replace {price:…} tokens; drop "from {token}/mo"-style phrases whose price is unknown. */
export async function resolvePriceTokens(text: string, prices: SeoPrices | (() => Promise<SeoPrices>)): Promise<string> {
  if (!text.includes("{price:")) return text;
  const p = typeof prices === "function" ? await prices() : prices;
  const lookup = (key: string): number | null => {
    if (key === "vps") return p.vps;
    if (key === "hosting") return p.hosting;
    if (key === "email") return p.email;
    if (key.startsWith("game:")) return p.game.get(key.slice(5)) ?? null;
    return null;
  };
  return text
    .replace(/\s*(?:from|start at|starting at)?\s*\{price:([a-z0-9:_-]+)\}\/mo(?:,\s*all-in)?/gi, (m, key: string) => {
      const c = lookup(key);
      if (c == null) return "";
      return m.replace(/\{price:[a-z0-9:_-]+\}/i, usd(c));
    })
    .replace(/\s+([.,])/g, "$1")
    .replace(/\s{2,}/g, " ")
    .trim();
}

import "server-only";
import { headers } from "next/headers";
import { db } from "./db";
import { scheduleNode, regionAvailability } from "./node-capacity";
import { countryFromHeaders } from "./geo-currency";
import { countryFromRequestIp } from "./geo-ip";
import { decideRegion, regionForCountry, type RegionSource, type RegionStatusMap } from "./region-pick";

/**
 * Server-side region resolution + placement for VPS and game orders
 * (2026-10-01 root-cause fix — see lib/region-pick.ts for the incident).
 *
 * Contract:
 *  - the region is ALWAYS decided here: explicit (what the customer picked) or
 *    resolved from their country ("geo") or the home default ("default");
 *  - the node is chosen only WITHIN that region and a customer/partner's chosen region is HONOURED even when it is
 *    nearly full (owner policy 2026-10-01: "customer and partners get the region they want, not what the system
 *    wants") — capacity is our problem to fix (admin 'Region full' alert), never a reason to refuse or to move them;
 *  - the only refusal is a region with NO eligible node at all (disabled/unconfigured), which never moves the order
 *    to another region either — it lists the nearest regions and lets the customer choose.
 */

/** Best-known country for this customer: current request (CDN header, then IP) else their latest visit. */
export async function customerCountryHint(userId: string | null | undefined): Promise<string | null> {
  try {
    const h = await headers();
    const c = countryFromHeaders(h) || countryFromRequestIp(h);
    if (c) return c;
  } catch {
    // not in a request scope (webhook / worker) — fall through to stored visits
  }
  if (!userId) return null;
  try {
    const v = await db.visit.findFirst({
      where: { userId, country: { not: null } },
      orderBy: { createdAt: "desc" },
      select: { country: true },
    });
    return v?.country?.trim().toUpperCase() || null;
  } catch {
    return null;
  }
}

export type Placement =
  | { ok: true; node: { id: string; name: string; region: string } | null; region: string; source: RegionSource }
  | { ok: false; message: string; region: string; source: RegionSource; alternatives: string[] };

/**
 * Resolve region (explicit > geo > default) and pick a node inside it.
 * `country` (optional) overrides the lookup — used by tests/callers that
 * already know it.
 */
export async function placeInRegion(args: {
  ramMB: number;
  /** vCPU of the VM (CPU-aware placement). Omitted = 1. */
  vcpu?: number;
  templateVmid?: number | null;
  region?: string | null;
  provider?: "OVH" | "HETZNER";
  userId?: string | null;
  country?: string | null;
  product?: string;
}): Promise<Placement> {
  const explicit = (args.region ?? "").trim();
  const country = explicit ? null : args.country ?? (await customerCountryHint(args.userId));
  const target = explicit
    ? { region: explicit, source: "explicit" as RegionSource }
    : (() => {
        const g = regionForCountry(country);
        return { region: g.region, source: (g.known ? "geo" : "default") as RegionSource };
      })();

  const node = await scheduleNode(args.ramMB, {
    vcpu: args.vcpu,
    userId: args.userId ?? null,
    product: args.product,
    region: target.region,
    provider: args.provider,
    templateVmid: args.templateVmid,
    strict: false,
  });
  if (node) return { ok: true, node: { id: node.id, name: node.name, region: node.region }, region: target.region, source: target.source };

  // No node configured anywhere (dev/sandbox): nothing to refuse against — the
  // order keeps its legacy nodeId-less behaviour there. Real deployments always
  // have nodes, so this never masks a genuinely full region.
  if ((await db.node.count({ where: { enabled: true } })) === 0) {
    return { ok: true, node: null, region: target.region, source: target.source };
  }

  // Refusal: work out the alternatives from the same scheduler, never auto-pick one.
  let availability: RegionStatusMap = {};
  try {
    availability = await regionAvailability(args.ramMB, { templateVmid: args.templateVmid, vcpu: args.vcpu });
  } catch {
    availability = {};
  }
  availability[target.region] = "sold_out";
  const d = decideRegion({ explicitRegion: target.region, availability });
  if (d.ok) {
    // unreachable (target forced sold_out) — keep the type checker honest
