export async function generateMetadata({ params }: { params: Promise<{ slug: string }> }): Promise<Metadata> {
  const { slug } = await params;
  const user = await currentUser().catch(() => null);
  const p = await pageForViewer(slug, user).catch(() => null);
  if (!p) return cyrusMetadata("Page not found");
  const c = await communityForSlug(p.slug, user, { hasCyrus: false }).catch(() => null);
  const seo = modSeo(p, c);
  const m = await cyrusMetadata(seo.title, seo.description);
  // A private page (creator viewing it) is never indexable, launched or not.
  const open = p.visibility === "PUBLIC" && !p.hidden;
  return {
    ...m,
    ...(open ? {} : { robots: { index: false, follow: false } }),
    keywords: seo.keywords,
    alternates: { canonical: `/mods/cyrus/${p.slug}` },
    openGraph: { type: "website", title: seo.title, description: seo.description, url: seo.url, siteName: "Nxeon", images: [{ url: seo.image, alt: `${p.title}, a ${seo.game.name} plugin` }] },
    twitter: { card: "summary_large_image", title: seo.title, description: seo.description, images: [seo.image] },
  };
}

