// SEO for the public Cyrus mod page, derived ONLY from the mod's generated doc and its creator's listing
// (nothing invented). Pure, so it is unit-tested; the page and the metadata share one source of truth.
import type { PageView } from "./pages";
import type { CommunityView } from "./social";
import { gameForDoc } from "./game";

const APP = process.env.APP_URL ?? "https://nxeon.cloud";
const clip = (s: string, n: number) => (s.length <= n ? s : s.slice(0, n - 1).replace(/\s+\S*$/, "") + "…");
const flat = (s: string) => s.replace(/\s+/g, " ").trim();

export type ModFaq = { q: string; a: string };

export function modSeo(p: PageView, c: CommunityView | null) {
  const d = p.doc;
  const game = gameForDoc(d);
  const v = game.versions;
  const versionText = v.length ? (v.length === 1 ? v[0] : `${v[v.length - 1]}–${v[0]}`) : "";
  const tagline = c?.listing.tagline || d.tagline || "";
  const lead = tagline || (d.summary ? flat(d.summary).split(/(?<=[.!?])\s/)[0] : `A ${game.name} plugin made with Cyrus.`);
  const title = clip(`${p.title} — ${game.name} ${versionText ? versionText + " " : ""}Plugin | Cyrus Mods`, 70);
  const description = clip(flat(`${lead} Free ${game.name} ${game.software[0] ?? "Paper"} plugin${versionText ? ` for ${versionText}` : ""}${d.commands.length ? ` with ${d.commands.length} command${d.commands.length === 1 ? "" : "s"}` : ""}. Built with Cyrus, read the source, install on your server in one click.`), 158);
  const url = `${APP}/mods/cyrus/${p.slug}`;
  const image = c?.listing.banner?.url ?? c?.listing.photos[0]?.url ?? c?.listing.icon?.url ?? game.hero;
  const abs = (u: string) => (u.startsWith("http") ? u : `${APP}${u}`);
  const keywords = [...new Set([p.title, `${p.title} ${game.name} plugin`, `${game.name} ${game.software[0] ?? "Paper"} plugin`, ...(c?.listing.tags ?? []), `${game.name} mods`, "Cyrus"].map((k) => k.toLowerCase()))].slice(0, 12);

  const faq: ModFaq[] = [];
  if (d.summary) faq.push({ q: `What does ${p.title} do?`, a: clip(flat(d.summary), 600) });
  if (v.length) faq.push({ q: `Which ${game.name} versions does ${p.title} support?`, a: `${p.title} is built for ${game.name} ${v.join(", ")}. ${d.compat.note}` });
  faq.push({
    q: `How do I install ${p.title}?`,
    a: d.howToUse.length ? clip(flat(d.howToUse.map((s, i) => `${i + 1}. ${s}`).join(" ")), 600) : `Download the jar, drop it in your server's plugins folder and restart. Nxeon customers can install it on a ${game.name} server in one click.`,
  });
  if (d.commands.length) faq.push({ q: `What commands does ${p.title} add?`, a: clip(d.commands.slice(0, 8).map((x) => `${x.usage} (${flat(x.description)})`).join("; "), 600) });
  faq.push({ q: `Is ${p.title} free?`, a: `Yes. It is free to download (${p.license} licence) and its source code is available on the page. You only pay for the server it runs on.` });

  const jsonLd = {
    "@context": "https://schema.org",
    "@type": "SoftwareApplication",
    name: p.title,
    url,
    applicationCategory: "GameApplication",
    operatingSystem: `${game.name} ${game.platform}`,
    ...(versionText ? { softwareVersion: p.doc.versions.find((x) => x.buildId === d.currentBuildId)?.version ?? undefined } : {}),
    description,
    datePublished: p.publishedAt ?? p.createdAt,
    dateModified: p.updatedAt,
    // the public author tag (chosen username), linked to the creator page; never the personal account name
    author: { "@type": "Person", name: p.creator.name, ...(c?.creatorHandle ? { url: `${APP}/mods/cyrus/u/${c.creatorHandle}` } : {}) },
    publisher: { "@type": "Organization", name: "Nxeon", url: APP },
    image: [abs(image)],
    offers: { "@type": "Offer", price: "0", priceCurrency: "USD" },
    ...(c && c.stats.ratings.count > 0 && c.stats.ratings.average != null ? { aggregateRating: { "@type": "AggregateRating", ratingValue: c.stats.ratings.average.toFixed(1), reviewCount: c.stats.ratings.count } } : {}),
  };
  const breadcrumbs = {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: [
      { "@type": "ListItem", position: 1, name: "Home", item: APP },
      { "@type": "ListItem", position: 2, name: "Mods", item: `${APP}/mods` },
      { "@type": "ListItem", position: 3, name: "Cyrus Mods", item: `${APP}/mods/cyrus` },
      { "@type": "ListItem", position: 4, name: p.title, item: url },
    ],
  };
  const faqLd = { "@context": "https://schema.org", "@type": "FAQPage", mainEntity: faq.map((f) => ({ "@type": "Question", name: f.q, acceptedAnswer: { "@type": "Answer", text: f.a } })) };
  return { title, description, url, image: abs(image), keywords, faq, jsonLd, breadcrumbs, faqLd, game };
}

/** JSON for an inline ld+json script. Mod titles and descriptions are user-written, so `<` is escaped (a `</script>` in a title must not break out). */
export const safeJsonLd = (data: unknown) => JSON.stringify(data).replace(/</g, "\\u003c").replace(/\u2028/g, "\\u2028").replace(/\u2029/g, "\\u2029");

