/**
 * The ONE switch for the public Cyrus marketing page (/cyrus, the NXM page
 * app/nxm/cyrus) and every link to it (NXM nav tab + Products menu + mobile
 * sheet, the footer entry, the sitemap).
 *
 * A viewer may see it when EITHER
 *   - Setting cyrus_public_enabled is on (the owner's launch), OR
 *   - they are a private-preview account for "modbuilder" (lib/preview-access.ts,
 *     Setting preview_access_emails_modbuilder; default: the owner's own
 *     customer account), the same people who can open the studio today.
 * Everyone else gets a plain 404, exactly as if the route did not exist.
 *
 * Indexing: noindex unless the PUBLIC flag is on; the sitemap lists /cyrus only
 * when public (lib/sitemap-sections.ts EXCLUDE + cyrusPageSitemapPaths); the nav
 * and footer entries are injected only for viewers who pass this gate
 * (app/nxm/_components/cyrus-nav.ts). Fails CLOSED on any DB error.
 *
 * test/cyrus-page-gate.test.ts asserts all of the above, including that no file
 * outside the feature links to /cyrus.
 */
import { notFound } from "next/navigation";
import { getHost } from "./host";

export const CYRUS_PUBLIC_FLAG = "cyrus_public_enabled";
export const CYRUS_PAGE_PATH = "/cyrus";
/** Where the page's buttons open the studio. */
export const CYRUS_STUDIO_PATH = "/dashboard/cyrus";

/** Pure decision (unit-tested): render, or 404. */
export function cyrusPageDecision(flagOn: boolean, previewUser = false): "render" | "not-found" {
  return flagOn || previewUser ? "render" : "not-found";
}

export async function cyrusPublicEnabled(): Promise<boolean> {
  try {
    return await getHost().settings.getBool(CYRUS_PUBLIC_FLAG, false);
  } catch {
    return false; // fail CLOSED: a DB hiccup must never expose an unreleased page
  }
}

export type CyrusPageAccess = { allowed: boolean; isPublic: boolean; preview: boolean };

/** Access for an already-loaded user (nav, footer, layouts). Never throws. */
export async function cyrusPageAccessFor(user: { email?: string | null } | null | undefined): Promise<CyrusPageAccess> {
  const isPublic = await cyrusPublicEnabled();
  const preview = !isPublic && (await getHost().access.isPreviewUser(user, "modbuilder"));
  return { allowed: cyrusPageDecision(isPublic, preview) === "render", isPublic, preview };
}

/** Route guard: 404 unless the viewer may see the Cyrus page. */
export async function requireCyrusPageAccess(): Promise<CyrusPageAccess> {
  let user = null;
  try {
    user = await getHost().auth.currentUser();
  } catch {
    user = null;
  }
  const access = await cyrusPageAccessFor(user);
  if (!access.allowed) notFound();
  return access;
}

/** Sitemap paths contributed by this feature (empty unless PUBLIC: a preview never advertises). */
export function cyrusPageSitemapPaths(flagOn: boolean): string[] {
  return flagOn ? [CYRUS_PAGE_PATH] : [];
}
